#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

struct Ship {
    int id;   // 原始编号
    int x;    // 分配后的坐标
    int v;    // 速度
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<Ship> ships(n);
    vector<int> points(n);

    for (int i = 0; i < n; i++) {
        ships[i].id = i;
        cin >> points[i] >> ships[i].v;
    }

    // 坐标从小到大排序
    sort(points.begin(), points.end());
    // 飞船按速度从小到大排序
    sort(ships.begin(), ships.end(), [](const Ship& a, const Ship& b) {
        return a.v < b.v;
    });

    // 分配坐标
    for (int i = 0; i < n; i++) {
        ships[i].x = points[i];
    }

    // 按原始编号排序
    sort(ships.begin(), ships.end(), [](const Ship& a, const Ship& b) {
        return a.id < b.id;
    });

    // 输出
    for (const auto& s : ships) {
        cout << s.x << " " << s.v << '\n';
    }
    return 0;
}
